import os as _os
"""Pharmacies API: self-serve onboarding application + admin review/approval.

On approval, Solera.0 creates the Pharmacy registry row + PharmacyDirectory + ConsumerSettings
(defaults PRIVATE). The pharmacy's own Solera Turso DB must be connected by an admin (the
encrypted db_token) before it appears in the public marketplace search.
"""
import json
import time
from django.http import JsonResponse
from django.views.decorators.csrf import csrf_exempt
from django.views.decorators.http import require_POST, require_GET
from django.shortcuts import get_object_or_404

from .models import PharmacyApplication, Pharmacy, PharmacyDirectory, ConsumerSettings, Plan

PLATFORM_ADMIN_EMAILS = [e.strip().lower() for e in (_os.environ.get("PLATFORM_ADMIN_EMAILS") or "").split(",") if e.strip()]


def _now():
    return int(time.time() * 1000)


def _admin_guard(request):
    """Minimal admin check: x-admin-email header must be a platform admin (demo gate)."""
    email = (request.headers.get("x-admin-email") or "").strip().lower()
    if email not in PLATFORM_ADMIN_EMAILS:
        return False
    return True


@csrf_exempt
@require_POST
def apply(request):
    body = json.loads(request.body or "{}")
    required = ["name", "contact_phone", "city"]
    missing = [k for k in required if not body.get(k)]
    if missing:
        return JsonResponse({"error": f"missing: {', '.join(missing)}"}, status=400)
    app = PharmacyApplication.objects.create(
        name=body["name"],
        contact_phone=body["contact_phone"],
        contact_email=body.get("contact_email", ""),
        city=body.get("city", ""),
        county=body.get("county", ""),
        address=body.get("address", ""),
        ppb_license=body.get("ppb_license", ""),
        created_at=_now(),
    )
    return JsonResponse({
        "application_id": app.id,
        "status": app.status,
        "message": "Application received. Our team verifies your PPB licence, then lists you.",
    }, status=201)


@require_GET
def list_applications(request):
    if not _admin_guard(request):
        return JsonResponse({"error": "admin only"}, status=403)
    qs = PharmacyApplication.objects.all().order_by("-created_at")
    out = [{
        "id": a.id, "name": a.name, "city": a.city, "county": a.county,
        "contact_phone": a.contact_phone, "ppb_license": a.ppb_license,
        "is_verified": a.is_verified, "status": a.status, "created_at": a.created_at,
    } for a in qs]
    return JsonResponse({"applications": out})


@csrf_exempt
@require_POST
def approve(request, app_id):
    if not _admin_guard(request):
        return JsonResponse({"error": "admin only"}, status=403)
    app = get_object_or_404(PharmacyApplication, id=app_id)
    if app.status == "approved":
        return JsonResponse({"message": "already approved"})
    body = json.loads(request.body or "{}")
    # The pharmacy's Turso credentials are provided by an admin at approval time.
    turso_db_url = body.get("turso_db_url")
    db_token_encrypted = body.get("db_token_encrypted")
    if not (turso_db_url and db_token_encrypted):
        return JsonResponse(
            {"error": "turso_db_url and db_token_encrypted required to approve (connects the pharmacy DB)"},
            status=400,
        )
    slug = app.name.lower().replace(" ", "-").replace("'", "")[:120]
    plan = Plan.objects.first()
    pharmacy = Pharmacy.objects.create(
        tenant_id=f"app-{app.id}",
        name=app.name,
        slug=slug,
        turso_db_url=turso_db_url,
        db_token_encrypted=db_token_encrypted,
        plan=plan,
        status="active",
        created_at=_now(),
    )
    PharmacyDirectory.objects.create(
        pharmacy=pharmacy, display_name=app.name, city=app.city, county=app.county,
        address=app.address, is_verified=app.is_verified, is_active=True, created_at=_now(),
    )
    ConsumerSettings.objects.create(
        pharmacy=pharmacy, is_public=False, display_name=app.name,
        address=app.address, phone=app.contact_phone, created_at=_now(), updated_at=_now(),
    )
    app.status = "approved"
    app.reviewed_at = _now()
    app.save()
    return JsonResponse({
        "pharmacy_id": pharmacy.id, "slug": slug, "status": "approved",
        "is_public": False,
        "message": "Pharmacy created (private). Enable public storefront in ConsumerSettings.",
    })

