import "server-only";
import { eq } from "drizzle-orm";
import { getMetadataDb } from "@/db/client";
import * as schema from "@/db/schema/tenant";
import { subscriptions } from "@/db/schema/metadata";
import { getTransactionStatus } from "@/lib/payhero";
import { getTenantContext } from "@/lib/tenant";
import { confirmSalePayment } from "@/lib/payments/confirm-sale";
import { confirmSubscriptionPayment } from "@/lib/billing/payhero";
import {
  isSalePaymentReference,
  isSubscriptionPaymentReference,
  parseSalePaymentReference,
  buildSalePaymentReference,
} from "@/lib/payments/reference";
import { parsePayHeroTransactionOutcome } from "@/lib/payments/payhero-status";

export type PaymentProgressStatus =
  | "pending"
  | "completed"
  | "failed"
  | "not_found";

export type PaymentStatusResult = {
  status: PaymentProgressStatus;
  kind: "sale" | "subscription";
  label?: string;
  reference: string;
};

async function reconcileFromPayHero(
  kind: "sale" | "subscription",
  confirmRef: string,
  payheroRef: string,
) {
  const remote = await getTransactionStatus(payheroRef);
  if (!remote) return;

  const outcome = parsePayHeroTransactionOutcome(remote);
  if (outcome === "pending") return;

  if (outcome === "completed") {
    if (kind === "subscription") {
      await confirmSubscriptionPayment(confirmRef, true);
    } else {
      await confirmSalePayment(confirmRef, true);
    }
  } else {
    if (kind === "subscription") {
      await confirmSubscriptionPayment(confirmRef, false);
    } else {
      await confirmSalePayment(confirmRef, false);
    }
  }
}

export async function getPaymentStatus(
  userId: string,
  tenantId: string,
  reference: string,
): Promise<PaymentStatusResult> {
  const db = getMetadataDb();
  const [sub] = await db
    .select()
    .from(subscriptions)
    .where(eq(subscriptions.tenantId, tenantId))
    .limit(1);

  const isSubscriptionRef =
    isSubscriptionPaymentReference(reference) ||
    (sub?.stripeSubscriptionId != null && sub.stripeSubscriptionId === reference);

  if (isSubscriptionRef && sub) {
    const payheroRef = sub.stripeSubscriptionId;
    const matchesCurrentPayment =
      isSubscriptionPaymentReference(reference) ||
      (payheroRef != null && payheroRef === reference);

    if (sub.status === "pending" && payheroRef && matchesCurrentPayment) {
      await reconcileFromPayHero("subscription", payheroRef, payheroRef);
      const [updated] = await db
        .select()
        .from(subscriptions)
        .where(eq(subscriptions.tenantId, tenantId))
        .limit(1);
      if (updated?.status === "active") {
        return { status: "completed", kind: "subscription", reference, label: "Subscription active" };
      }
      if (updated?.status === "failed") {
        return { status: "failed", kind: "subscription", reference, label: "Payment failed or cancelled" };
      }
    }

    if (sub.status === "active" && matchesCurrentPayment) {
      return { status: "completed", kind: "subscription", reference, label: "Subscription active" };
    }
    if (sub.status === "failed" && matchesCurrentPayment) {
      return { status: "failed", kind: "subscription", reference, label: "Payment failed or cancelled" };
    }
    if (sub.status === "pending" && matchesCurrentPayment) {
      return { status: "pending", kind: "subscription", reference, label: "Waiting for M-Pesa PIN" };
    }
    if (sub.status === "active" || sub.status === "failed") {
      return { status: "not_found", kind: "subscription", reference };
    }
    return { status: "pending", kind: "subscription", reference, label: "Waiting for M-Pesa PIN" };
  }

  if (isSubscriptionPaymentReference(reference)) {
    return { status: "not_found", kind: "subscription", reference };
  }

  const ctx = await getTenantContext(userId, tenantId);
  if (!ctx) return { status: "not_found", kind: "sale", reference };

  const parsed = parseSalePaymentReference(reference);
  const receiptNumber = parsed?.receiptNumber ?? (reference.startsWith("RCP-") ? reference : null);
  if (!receiptNumber) return { status: "not_found", kind: "sale", reference };

  const [sale] = await ctx.tenantDb
    .select()
    .from(schema.sales)
    .where(eq(schema.sales.receiptNumber, receiptNumber))
    .limit(1);

  if (!sale) return { status: "not_found", kind: "sale", reference };

  if (sale.status === "pending_payment" && sale.mpesaTxnId) {
    const saleRef = parsed
      ? reference
      : buildSalePaymentReference(
          tenantId,
          sale.receiptNumber,
        );
    await reconcileFromPayHero("sale", saleRef, sale.mpesaTxnId);
    const [updated] = await ctx.tenantDb
      .select()
      .from(schema.sales)
      .where(eq(schema.sales.id, sale.id))
      .limit(1);
    if (updated?.status === "completed") {
      return {
        status: "completed",
        kind: "sale",
        reference,
        label: `Receipt ${updated.receiptNumber}`,
      };
    }
    if (updated?.status === "payment_failed") {
      return {
        status: "failed",
        kind: "sale",
        reference,
        label: `Receipt ${updated.receiptNumber}`,
      };
    }
  }

  if (sale.status === "completed") {
    return { status: "completed", kind: "sale", reference, label: `Receipt ${sale.receiptNumber}` };
  }
  if (sale.status === "payment_failed") {
    return { status: "failed", kind: "sale", reference, label: `Receipt ${sale.receiptNumber}` };
  }
  if (isSalePaymentReference(reference)) {
    return { status: "pending", kind: "sale", reference, label: `Receipt ${sale.receiptNumber}` };
  }

  return { status: "not_found", kind: "sale", reference };
}

