import "server-only";
import { logger } from "@/lib/logger";
import { payHeroCallbackUrl } from "@/lib/payhero-webhook";

const PAYHERO_API = "https://backend.payhero.co.ke/api/v2";

export type StkPushResult = {
  success: boolean;
  checkoutRequestId?: string;
  reference?: string;
  message: string;
  simulated?: boolean;
};

function payHeroConfigured(): boolean {
  return !!(
    process.env.PAYHERO_AUTH_TOKEN &&
    process.env.PAYHERO_CHANNEL_ID
  );
}

function authHeader(): string {
  const token = process.env.PAYHERO_AUTH_TOKEN!;
  return token.startsWith("Basic ") ? token : `Basic ${token}`;
}

function callbackUrl(): string {
  return payHeroCallbackUrl();
}

/** Normalize Kenyan phone to 07XXXXXXXX or 2547XXXXXXXX for Pay Hero */
export function normalizeKenyanPhone(phone: string): string {
  const digits = phone.replace(/\D/g, "");
  if (digits.startsWith("254")) return `0${digits.slice(3)}`;
  if (digits.startsWith("0")) return digits;
  if (digits.length === 9) return `0${digits}`;
  return digits;
}

/**
 * Initiate M-Pesa STK via Pay Hero Kenya.
 * @see https://payherokenya.com — POST /api/v2/payments
 */
export async function initiateStkPush(params: {
  phone: string;
  amount: number;
  accountReference: string;
  transactionDesc: string;
  customerName?: string;
}): Promise<StkPushResult> {
  const phone = normalizeKenyanPhone(params.phone);
  const amountKes = Math.max(1, Math.round(params.amount / 100));

  if (!payHeroConfigured()) {
    if (process.env.NODE_ENV === "production") {
      return { success: false, message: "PayHero is not configured" };
    }
    const id = `SIM-${Date.now()}`;
    logger.info("payhero_stk_simulated", { phone, amountKes, id });
    return {
      success: true,
      checkoutRequestId: id,
      reference: id,
      message: "STK push simulated (set PAYHERO_AUTH_TOKEN + PAYHERO_CHANNEL_ID)",
      simulated: true,
    };
  }

  const channelId = Number(process.env.PAYHERO_CHANNEL_ID);
  const res = await fetch(`${PAYHERO_API}/payments`, {
    method: "POST",
    headers: {
      Authorization: authHeader(),
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      amount: amountKes,
      phone_number: phone,
      channel_id: channelId,
      provider: "m-pesa",
      external_reference: params.accountReference.slice(0, 64),
      customer_name: params.customerName ?? "Solera Customer",
      callback_url: callbackUrl(),
    }),
  });

  const data = (await res.json()) as {
    success?: boolean;
    status?: string;
    reference?: string;
    CheckoutRequestID?: string;
    error_message?: string;
  };

  if (!res.ok || !data.success) {
    logger.error("payhero_stk_failed", { data, status: res.status });
    return {
      success: false,
      message: data.error_message ?? "Pay Hero STK push failed",
    };
  }

  logger.info("payhero_stk_sent", {
    reference: data.reference,
    checkoutRequestId: data.CheckoutRequestID,
  });

  return {
    success: true,
    checkoutRequestId: data.CheckoutRequestID,
    reference: data.reference,
    message: data.status ?? "STK push queued",
  };
}

export async function getTransactionStatus(reference: string) {
  if (!payHeroConfigured()) return null;

  const res = await fetch(
    `${PAYHERO_API}/transaction-status?reference=${encodeURIComponent(reference)}`,
    {
      headers: { Authorization: authHeader() },
    },
  );

  if (!res.ok) return null;
  return res.json() as Promise<{
    success: boolean;
    status: string;
    reference: string;
    provider_reference?: string;
  }>;
}

export async function getPaymentChannels() {
  if (!payHeroConfigured()) return [];

  const res = await fetch(`${PAYHERO_API}/payment_channels?is_active=true`, {
    headers: { Authorization: authHeader() },
  });

  if (!res.ok) return [];
  const data = (await res.json()) as { payment_channels?: unknown[] };
  return data.payment_channels ?? [];
}

