/** Pay Hero external reference for POS M-Pesa sales. */
export function buildSalePaymentReference(tenantId: string, receiptNumber: string) {
  return `SALE-${tenantId.slice(0, 8)}-${receiptNumber}`;
}

export function parseSalePaymentReference(ref: string): { tenantPrefix: string; receiptNumber: string } | null {
  const match = ref.match(/^SALE-([a-zA-Z0-9]+)-(.+)$/);
  if (!match) return null;
  return { tenantPrefix: match[1], receiptNumber: match[2] };
}

export function isSubscriptionPaymentReference(ref: string) {
  return ref.startsWith("SUB-");
}

export function isSalePaymentReference(ref: string) {
  return ref.startsWith("SALE-") || ref.startsWith("RCP-");
}

