import assert from "node:assert/strict";
import { describe, it, beforeEach, afterEach } from "node:test";
import { payHeroCallbackUrl, verifyPayHeroCallback } from "@/lib/payhero-webhook";

describe("payHeroCallbackUrl", () => {
  const env = process.env;

  beforeEach(() => {
    process.env = { ...env };
  });

  afterEach(() => {
    process.env = env;
  });

  it("appends secret query param when configured", () => {
    process.env.PAYHERO_CALLBACK_URL = "https://solerasite.vercel.app/api/payhero/callback";
    process.env.PAYHERO_CALLBACK_SECRET = "abc123";
    const url = payHeroCallbackUrl();
    assert.equal(url, "https://solerasite.vercel.app/api/payhero/callback?secret=abc123");
  });
});

describe("verifyPayHeroCallback", () => {
  const env = process.env;

  beforeEach(() => {
    process.env = { ...env, NODE_ENV: "production", PAYHERO_CALLBACK_SECRET: "test-secret-value" };
  });

  afterEach(() => {
    process.env = env;
  });

  it("accepts matching secret in query string", () => {
    const req = new Request(
      "https://solerasite.vercel.app/api/payhero/callback?secret=test-secret-value",
      { method: "POST" },
    );
    assert.equal(verifyPayHeroCallback(req), true);
  });

  it("rejects missing secret", () => {
    const req = new Request("https://solerasite.vercel.app/api/payhero/callback", { method: "POST" });
    assert.equal(verifyPayHeroCallback(req), false);
  });
});
