import "server-only";

const BREVO_API = "https://api.brevo.com/v3/smtp/email";

function parseSender(): { name: string; email: string } {
  const raw = process.env.BREVO_FROM ?? process.env.BREVO_SENDER_EMAIL ?? "noreply@solera.co.ke";
  const match = raw.match(/^(.+?)\s*<([^>]+)>$/);
  if (match) return { name: match[1].trim(), email: match[2].trim() };
  return { name: "Solera", email: raw };
}

export type SendEmailResult = { ok: true } | { ok: false; error: string };

export async function sendEmail(
  to: string,
  subject: string,
  html: string,
): Promise<SendEmailResult> {
  const apiKey = process.env.BREVO_API_KEY;
  if (!apiKey) {
    const error = "BREVO_API_KEY not configured";
    console.warn("[solera]", error, { to, subject });
    return { ok: false, error };
  }

  const sender = parseSender();
  const res = await fetch(BREVO_API, {
    method: "POST",
    headers: {
      "api-key": apiKey,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({
      sender,
      to: [{ email: to }],
      subject,
      htmlContent: html,
    }),
  });

  if (!res.ok) {
    const body = await res.text();
    console.error("[solera] Brevo error:", body);
    let message = "Brevo rejected the email";
    try {
      const parsed = JSON.parse(body) as { message?: string };
      if (parsed.message) message = parsed.message;
    } catch {
      // use default message
    }
    return { ok: false, error: message };
  }
  return { ok: true };
}

