import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { parsePayHeroCallbackOutcome, parsePayHeroTransactionOutcome } from "./payhero-status";

describe("parsePayHeroTransactionOutcome", () => {
  it("treats QUEUED with API success as pending", () => {
    assert.equal(parsePayHeroTransactionOutcome({ success: true, status: "QUEUED" }), "pending");
  });

  it("treats SUCCESS status as completed", () => {
    assert.equal(parsePayHeroTransactionOutcome({ success: true, status: "SUCCESS" }), "completed");
  });

  it("treats FAILED status as failed", () => {
    assert.equal(parsePayHeroTransactionOutcome({ success: true, status: "FAILED" }), "failed");
  });

  it("uses ResultCode when present", () => {
    assert.equal(parsePayHeroTransactionOutcome({ ResultCode: 0, status: "Failed" }), "completed");
    assert.equal(parsePayHeroTransactionOutcome({ ResultCode: 1032 }), "failed");
  });
});

describe("parsePayHeroCallbackOutcome", () => {
  it("does not treat webhook status true as payment success", () => {
    assert.equal(
      parsePayHeroCallbackOutcome({
        status: true,
        response: { ResultCode: 1032, Status: "Failed", ResultDesc: "Cancelled by user" },
      }),
      "failed",
    );
  });

  it("confirms success only on ResultCode 0", () => {
    assert.equal(
      parsePayHeroCallbackOutcome({
        status: true,
        response: { ResultCode: 0, Status: "Success" },
      }),
      "completed",
    );
  });
});

