"""Common views: health check, OTP auth (staff + consumer), research index."""
import os
import json
from django.http import JsonResponse
from django.views.decorators.csrf import csrf_exempt
from django.views.decorators.http import require_POST, require_GET


@require_GET
def health(request):
    return JsonResponse({"status": "ok", "service": "solera0", "mode": "django"})


