@csrf_exempt
@require_POST
def request_otp(request):
    """Generate a real OTP, store it (short TTL), and send it via Brevo SMS.
    `dev_otp` is only ever included in the response when settings.DEBUG is True — never
    in production, regardless of what the caller requests."""
    body = json.loads(request.body or "{}")
    phone = body.get("phone")
    role = body.get("role", "consumer")
    if not phone:
        return JsonResponse({"error": "phone required"}, status=400)

    code = _generate_otp()
    now = _now()
    OtpCode.objects.create(phone=phone, code=code, role=role, expires_at=now + OTP_TTL_MS, created_at=now)
    # Don't let old, unconsumed codes for this phone linger and become extra guessable surface.
    OtpCode.objects.filter(phone=phone, consumed=False).exclude(code=code, created_at=now).delete()

    sent = send_sms(phone, f"Your Solera.0 verification code is {code}. It expires in 5 minutes.")
    response = {"sent": bool(sent)}
    if settings.DEBUG:
        response["dev_otp"] = code
    return JsonResponse(response)


