@require_POST
def verify_otp(request):
    """Verify a real, stored OTP -> issue JWT (staff vs consumer determined by `role`)."""
    body = json.loads(request.body or "{}")
    phone = body.get("phone")
    otp = body.get("otp")
    role = body.get("role", "consumer")  # 'staff' or 'consumer'
    if not (phone and otp):
        return JsonResponse({"error": "phone and otp required"}, status=400)

    now = _now()
    match = (
        OtpCode.objects.filter(phone=phone, code=otp, role=role, consumed=False, expires_at__gte=now)
        .order_by("-created_at")
