from django.conf import settings
from django.http import JsonResponse
from django.views.decorators.csrf import csrf_exempt
from django.views.decorators.http import require_POST, require_GET
from django.shortcuts import get_object_or_404

from .models import ConsumerOrder, ConsumerOrderItem, ConsumerUser

OTP_ALPHABET = string.digits


def _now():
    return int(time.time() * 1000)


def _make_otp(n=6):
    return "".join(secrets.choice(OTP_ALPHABET) for _ in range(n))


def _auth_phone(request):
    """Extract consumer phone from a verified JWT (issued by common.views.verify_otp).
    Never trusts an unverified Authorization header value as a phone number directly.
    settings.DEBUG-only fallback to x-consumer-phone, for local testing without a real login."""
    auth = request.META.get("HTTP_AUTHORIZATION", "")
    if auth.startswith("Bearer "):
        token = auth[7:]
        try:
            from rest_framework_simplejwt.tokens import AccessToken
            validated = AccessToken(token)  # raises on invalid signature, tampering, or expiry
            from django.contrib.auth import get_user_model
            User = get_user_model()
            user = User.objects.get(id=validated["user_id"])
            if ":" in user.username:
                return user.username.split(":", 1)[1]
        except Exception:
            return None
    if settings.DEBUG:
        return request.headers.get("x-consumer-phone")
    return None

