"""PayHero (M-Pesa) API client. Mirrors Solera's src/lib/payhero.ts contract exactly —
same host, same endpoints, same auth scheme — since both apps share one PayHero account.

`consumer/views.py` already imports `initiate_stk` from this exact module path; it just
didn't exist before (the old implementation lived in payments/views.py under a different,
unconfirmed API host, so every consumer order's STK push silently failed with
ModuleNotFoundError, caught by place_order's broad except and never surfaced).
"""
import os
import re

import requests

PAYHERO_API = "https://backend.payhero.co.ke/api/v2"

FAILED_KEYWORDS = ("FAILED", "FAILURE", "CANCELLED", "CANCELED", "TIMEOUT", "DECLINED")


def _configured() -> bool:
    return bool(os.environ.get("PAYHERO_AUTH_TOKEN")) and bool(os.environ.get("PAYHERO_CHANNEL_ID"))


def _auth_header() -> str:
    token = os.environ["PAYHERO_AUTH_TOKEN"]
    return token if token.startswith("Basic ") else f"Basic {token}"


def normalize_kenyan_phone(phone: str) -> str:
    digits = re.sub(r"\D", "", phone or "")
    if digits.startswith("254"):
        return "0" + digits[3:]
    if digits.startswith("0"):
        return digits
    if len(digits) == 9:
        return "0" + digits
    return digits


def initiate_stk(phone: str, amount, reference: str, description: str = ""):
    """Initiate M-Pesa STK push. `amount` is whole KES — matches how consumer.views.place_order
    computes total_amount from raw unit_price * quantity (this backend's own models are not
    cents-denominated, unlike Solera's Next.js schema; see ConsumerOrderItem.unit_price)."""
    if not _configured():
        return {"success": False, "message": "PayHero is not configured"}

    payload = {
        "amount": max(1, int(round(float(amount)))),
        "phone_number": normalize_kenyan_phone(phone),
        "channel_id": int(os.environ["PAYHERO_CHANNEL_ID"]),
        "provider": "m-pesa",
        "external_reference": str(reference)[:64],
        "customer_name": (description or "Solera0 Customer")[:100],
        "callback_url": os.environ.get("PAYHERO_CALLBACK_URL", ""),
    }
    try:
        res = requests.post(
            f"{PAYHERO_API}/payments",
            headers={"Authorization": _auth_header(), "Content-Type": "application/json"},
            json=payload,
            timeout=15,
        )
    except requests.RequestException as e:
        return {"success": False, "message": str(e)}

    try:
        data = res.json() if res.content else {}
    except ValueError:
        data = {}

    if not res.ok or not data.get("success"):
        return {"success": False, "message": data.get("error_message", "PayHero STK push failed")}
    return {
        "success": True,
        "checkout_request_id": data.get("CheckoutRequestID"),
        "reference": data.get("reference"),
        "message": data.get("status", "STK push queued"),
    }


def get_transaction_status(reference: str):
    """Ask PayHero's own authenticated API for a transaction's real status. This is the
    source of truth used to reconcile an unverified webhook callback instead of trusting
    whatever outcome the callback body itself claims."""
    if not _configured():
        return None
    try:
        res = requests.get(
            f"{PAYHERO_API}/transaction-status",
            params={"reference": reference},
            headers={"Authorization": _auth_header()},
            timeout=10,
        )
    except requests.RequestException:
        return None
    if not res.ok:
        return None
    try:
        return res.json()
    except ValueError:
        return None


def parse_transaction_outcome(data: dict) -> str:
    """Returns 'completed' | 'failed' | 'pending'. Mirrors Solera's
    parsePayHeroTransactionOutcome exactly."""
    result_code = data.get("ResultCode", data.get("result_code"))
    if result_code not in (None, ""):
        try:
            return "completed" if int(result_code) == 0 else "failed"
        except (TypeError, ValueError):
            pass
    status = str(data.get("status") or "").upper()
    if status == "SUCCESS":
        return "completed"
    if status in ("QUEUED", "PENDING", "INITIATED"):
        return "pending"
    if any(k in status for k in FAILED_KEYWORDS):
        return "failed"
    return "pending"

