        except (TypeError, ValueError):
            pass
    status = str(data.get("status") or "").upper()
    if status == "SUCCESS":
        return "completed"
    if status in ("QUEUED", "PENDING", "INITIATED"):
        return "pending"
    if any(k in status for k in FAILED_KEYWORDS):
        return "failed"
    return "pending"

