"""PayHero (M-Pesa) STK push + callback handling (DD 7.3 / 8).

Reuses Solera PAYHERO_* env vars. On successful payment, marks the consumer order paid,
generates the pickup OTP (mirrors MYDAWA's order-verification OTP), and pushes the order into the
pharmacy's own Turso DB as a new online order (DD 7.3 fulfilment).
"""
import os
import json
import time
import secrets
import string

import requests
from django.http import JsonResponse
from django.views.decorators.csrf import csrf_exempt
from django.views.decorators.http import require_POST

from consumer.models import ConsumerOrder

OTP_ALPHABET = string.digits


def _now():
    return int(time.time() * 1000)


def _cfg():
    return {
        "auth": os.environ.get("PAYHERO_AUTH_TOKEN", ""),
        "account": os.environ.get("PAYHERO_ACCOUNT_ID", ""),
        "channel": os.environ.get("PAYHERO_CHANNEL_ID", ""),
        "callback": os.environ.get("PAYHERO_CALLBACK_URL", ""),
    }


def initiate_stk(phone, amount, reference, description=""):
    """Trigger M-Pesa STK push. Returns a dict (always) so callers fail-soft."""
    cfg = _cfg()
    if not cfg["auth"]:
        return {"ok": False, "error": "PAYHERO_AUTH_TOKEN not configured"}
    payload = {
        "amount": int(amount),
        "phone_number": phone,
        "channel_id": cfg["channel"],
        "account_id": cfg["account"],
        "external_reference": reference,
        "callback_url": cfg["callback"],
        "provider": "mpesa",
        "description": description or f"Solera0 {reference}",
    }
    try:
        resp = requests.post(
            "https://api.payhero.co.ke/v1/payments",
            json=payload,
            headers={"Authorization": cfg["auth"], "Content-Type": "application/json"},
            timeout=30,
        )
        data = resp.json() if resp.content else {}
        return {"ok": resp.ok, "data": data, "checkout_request_id": data.get("checkout_request_id")}
    except Exception as e:  # pragma: no cover - network failure
        return {"ok": False, "error": str(e)}


