import { NextResponse } from "next/server";
import { logger } from "@/lib/logger";
import { confirmSubscriptionPayment } from "@/lib/billing/payhero";
import { confirmSalePayment } from "@/lib/payments/confirm-sale";
import { isSalePaymentReference, isSubscriptionPaymentReference } from "@/lib/payments/reference";
import { parsePayHeroCallbackOutcome, reconcilePayHeroCallback } from "@/lib/payments/payhero-status";
import { verifyPayHeroCallback } from "@/lib/payhero-webhook";

function makaoCallbackUrl(): string {
  return (
    process.env.MAKAO_CALLBACK_URL?.replace(/\/$/, "") ||
    "https://makaosite.vercel.app/api/payhero/callback"
  );
}

async function forwardToMakao(req: Request, bodyText: string) {
  const url = new URL(req.url);
  const target = `${makaoCallbackUrl()}${url.search}`;
  const res = await fetch(target, {
    method: "POST",
    headers: {
      "Content-Type": req.headers.get("content-type") || "application/json",
      ...(req.headers.get("authorization") ? { Authorization: req.headers.get("authorization")! } : {}),
      ...(req.headers.get("x-payhero-signature")
        ? { "x-payhero-signature": req.headers.get("x-payhero-signature")! }
        : {}),
      ...(req.headers.get("x-callback-secret")
        ? { "x-callback-secret": req.headers.get("x-callback-secret")! }
        : {}),
    },
    body: bodyText,
  });
  const text = await res.text();
  return new NextResponse(text, {
    status: res.status,
    headers: { "Content-Type": res.headers.get("content-type") || "application/json" },
  });
}

/**
 * Pay Hero payment callback.
 * @see https://payherokenya.com — Payment Callback payload
 */
export async function POST(req: Request) {
  const bodyText = await req.text();
  let body: Record<string, unknown>;
  try {
    body = JSON.parse(bodyText) as Record<string, unknown>;
  } catch {
    return NextResponse.json({ status: false, error: "Invalid JSON" }, { status: 400 });
  }

  const verification = verifyPayHeroCallback(req, { body });
  if (verification === "rejected") {
    logger.warn("payhero_callback_unauthorized");
    return NextResponse.json({ status: false, error: "Unauthorized" }, { status: 401 });
  }

  try {
    const response = (body.response ?? body) as Record<string, unknown>;
    const externalRef = String(response.ExternalReference ?? response.external_reference ?? "");

    if (externalRef.startsWith("MAKA-")) {
      logger.info("payhero_callback_forward_makao", { externalRef });
      return forwardToMakao(req, bodyText);
    }

    // Unverified (no matching shared secret): don't trust the body's claimed outcome —
    // it's exactly as forgeable as this request itself. Ask PayHero's own API instead.
    const outcome =
      verification === "verified"
        ? parsePayHeroCallbackOutcome(body)
        : externalRef
          ? await reconcilePayHeroCallback(externalRef)
          : "pending";

    if (verification === "unverified_shape") {
      logger.warn("payhero_callback_unverified_reconciled", { externalRef, outcome });
    }

    if (externalRef && outcome !== "pending") {
      const ref = externalRef;
      const success = outcome === "completed";
      if (isSubscriptionPaymentReference(ref)) {
        await confirmSubscriptionPayment(ref, success);
      } else if (isSalePaymentReference(ref)) {
        await confirmSalePayment(ref, success);
      } else {
        logger.warn("payhero_callback_unknown_ref", { externalRef: ref });
      }
    } else if (externalRef && outcome === "pending") {
      logger.info("payhero_callback_non_terminal", { externalRef });
    }

    return NextResponse.json({ status: true });
  } catch (e) {
    logger.error("payhero_callback_error", { error: String(e) });
    return NextResponse.json({ status: false }, { status: 500 });
  }
}

