/** Pay Hero payment outcome — not the same as HTTP/API `success` flags. */

export type PayHeroPaymentOutcome = "pending" | "completed" | "failed";

const FAILED_STATUS_KEYWORDS = ["FAILED", "FAILURE", "CANCELLED", "CANCELED", "TIMEOUT", "DECLINED"];

export function parsePayHeroTransactionOutcome(data: {
  success?: boolean;
  status?: string;
  ResultCode?: number | string;
  result_code?: number | string;
}): PayHeroPaymentOutcome {
  const resultCode = data.ResultCode ?? data.result_code;
  if (resultCode !== undefined && resultCode !== null && resultCode !== "") {
    return Number(resultCode) === 0 ? "completed" : "failed";
  }

  const status = String(data.status ?? "").toUpperCase();
  if (status === "SUCCESS") return "completed";
  if (status === "QUEUED" || status === "PENDING" || status === "INITIATED") return "pending";
  if (FAILED_STATUS_KEYWORDS.some((k) => status.includes(k))) return "failed";

  return "pending";
}

/** Callback body — `status: true` only means the webhook was accepted, not paid. */
export function parsePayHeroCallbackOutcome(body: Record<string, unknown>): PayHeroPaymentOutcome {
  const response = (body.response ?? body) as Record<string, unknown>;
  const fromResponse = parsePayHeroTransactionOutcome({
    ResultCode: response.ResultCode as number | string | undefined,
    result_code: response.result_code as number | string | undefined,
    status: (response.Status ?? response.status) as string | undefined,
  });

  if (fromResponse !== "pending") return fromResponse;

  const topStatus = String(body.status ?? "").toUpperCase();
  if (topStatus === "SUCCESS") return "completed";
  if (FAILED_STATUS_KEYWORDS.some((k) => topStatus.includes(k))) return "failed";

  return "pending";
}

