import "server-only";
import { logger } from "@/lib/logger";
import { payHeroCallbackUrl } from "@/lib/payhero-webhook";
import { parsePayHeroTransactionOutcome, type PayHeroPaymentOutcome } from "@/lib/payments/payhero-status";

const PAYHERO_API = "https://backend.payhero.co.ke/api/v2";

export type StkPushResult = {
  success: boolean;
  checkoutRequestId?: string;
  reference?: string;
  message: string;
  simulated?: boolean;
};

function payHeroConfigured(): boolean {
  return !!(
    process.env.PAYHERO_AUTH_TOKEN &&
    process.env.PAYHERO_CHANNEL_ID
  );
}

function authHeader(): string {
  const token = process.env.PAYHERO_AUTH_TOKEN!;
  return token.startsWith("Basic ") ? token : `Basic ${token}`;
}

function callbackUrl(): string {
  return payHeroCallbackUrl();
}

/** Normalize Kenyan phone to 07XXXXXXXX or 2547XXXXXXXX for Pay Hero */
export function normalizeKenyanPhone(phone: string): string {
  const digits = phone.replace(/\D/g, "");
  if (digits.startsWith("254")) return `0${digits.slice(3)}`;
  if (digits.startsWith("0")) return digits;
  if (digits.length === 9) return `0${digits}`;
  return digits;
}

/**
 * Initiate M-Pesa STK via Pay Hero Kenya.
 * @see https://payherokenya.com — POST /api/v2/payments
 */
export async function initiateStkPush(params: {
  phone: string;
  amount: number;
  accountReference: string;
  transactionDesc: string;
  customerName?: string;
}): Promise<StkPushResult> {
  const phone = normalizeKenyanPhone(params.phone);
  const amountKes = Math.max(1, Math.round(params.amount / 100));

  if (!payHeroConfigured()) {
    if (process.env.NODE_ENV === "production") {
      return { success: false, message: "PayHero is not configured" };
    }
    const id = `SIM-${Date.now()}`;
    logger.info("payhero_stk_simulated", { phone, amountKes, id });
    return {
      success: true,
      checkoutRequestId: id,
      reference: id,
      message: "STK push simulated (set PAYHERO_AUTH_TOKEN + PAYHERO_CHANNEL_ID)",
      simulated: true,
    };
  }

  const channelId = Number(process.env.PAYHERO_CHANNEL_ID);
  const res = await fetch(`${PAYHERO_API}/payments`, {
    method: "POST",
    headers: {
      Authorization: authHeader(),
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      amount: amountKes,
      phone_number: phone,
      channel_id: channelId,
      provider: "m-pesa",
      external_reference: params.accountReference.slice(0, 64),
      customer_name: params.customerName ?? "Solera Customer",
      callback_url: callbackUrl(),
    }),
  });

  const data = (await res.json()) as {
    success?: boolean;
    status?: string;
    reference?: string;
    CheckoutRequestID?: string;
    error_message?: string;
  };

  if (!res.ok || !data.success) {
    logger.error("payhero_stk_failed", { data, status: res.status });
    return {
      success: false,
      message: data.error_message ?? "Pay Hero STK push failed",
    };
  }

  logger.info("payhero_stk_sent", {
    reference: data.reference,
    checkoutRequestId: data.CheckoutRequestID,
  });

  return {
    success: true,
    checkoutRequestId: data.CheckoutRequestID,
    reference: data.reference,
    message: data.status ?? "STK push queued",
  };
}

export async function getTransactionStatus(reference: string) {
  if (!payHeroConfigured()) return null;

  const res = await fetch(
    `${PAYHERO_API}/transaction-status?reference=${encodeURIComponent(reference)}`,
    {
      headers: { Authorization: authHeader() },
    },
  );

  if (!res.ok) return null;
  return res.json() as Promise<{
    success: boolean;
    status: string;
    reference: string;
    provider_reference?: string;
  }>;
}

export async function getPaymentChannels() {
  if (!payHeroConfigured()) return [];

  const res = await fetch(`${PAYHERO_API}/payment_channels?is_active=true`, {
    headers: { Authorization: authHeader() },
  });

  if (!res.ok) return [];
  const data = (await res.json()) as { payment_channels?: unknown[] };
  return data.payment_channels ?? [];
}

/**
 * Source of truth for an UNVERIFIED webhook (see verifyPayHeroCallback's "unverified_shape"
 * case): ignore what the request body claims and ask PayHero's own authenticated API for
 * the real status of this reference instead. A forged callback can shape a body correctly,
 * but it can't make PayHero's API return "completed" for a transaction that never actually
 * succeeded. Returns "pending" (i.e. do nothing) if PayHero can't confirm it either way,
 * rather than ever trusting the unverified body.
 */
export async function reconcilePayHeroCallback(externalRef: string): Promise<PayHeroPaymentOutcome> {
  const remote = await getTransactionStatus(externalRef);
  if (!remote) return "pending";
  return parsePayHeroTransactionOutcome(remote);
}

import assert from "node:assert/strict";
import { describe, it, beforeEach, afterEach } from "node:test";
import { payHeroCallbackUrl, verifyPayHeroCallback } from "@/lib/payhero-webhook";

describe("payHeroCallbackUrl", () => {
  const env = process.env;

  beforeEach(() => {
    process.env = { ...env };
  });

  afterEach(() => {
    process.env = env;
  });

  it("appends secret query param when configured", () => {
    process.env.PAYHERO_CALLBACK_URL = "https://solerasite.vercel.app/api/payhero/callback";
    process.env.PAYHERO_CALLBACK_SECRET = "abc123";
    const url = payHeroCallbackUrl();
    assert.equal(url, "https://solerasite.vercel.app/api/payhero/callback?secret=abc123");
  });
});

describe("verifyPayHeroCallback", () => {
  const env = process.env;

  beforeEach(() => {
    process.env = { ...env, NODE_ENV: "production", PAYHERO_CALLBACK_SECRET: "test-secret-value" };
  });

  afterEach(() => {
    process.env = env;
  });

  // Matches the real call site (src/app/api/payhero/callback/route.ts), which always
  // passes { body } as the second argument — a prior version of this test called
  // verifyPayHeroCallback(req) with no second argument, so it never actually exercised
  // the shape-only fallback path production traffic goes through.
  it("accepts matching secret in query string", () => {
    const req = new Request(
      "https://solerasite.vercel.app/api/payhero/callback?secret=test-secret-value",
      { method: "POST" },
    );
    assert.equal(verifyPayHeroCallback(req, { body: {} }), "verified");
  });

  it("rejects a body with no secret and no recognizable PayHero shape", () => {
    const req = new Request("https://solerasite.vercel.app/api/payhero/callback", { method: "POST" });
    assert.equal(verifyPayHeroCallback(req, { body: {} }), "rejected");
  });

  // The fix under test: a correctly-shaped but unsigned body (exactly what a forged
  // request looks like) must NOT come back "verified" — callers are required to
  // independently reconcile it with PayHero's own API (see payhero-status.test.ts /
  // reconcilePayHeroCallback) before trusting anything it claims.
  it("returns unverified_shape — not verified — for a shaped body with no matching secret", () => {
    const req = new Request("https://solerasite.vercel.app/api/payhero/callback", { method: "POST" });
    const forgedBody = { response: { ExternalReference: "SALE-abcd1234-RCP-0001", Status: "Success" } };
    const result = verifyPayHeroCallback(req, { body: forgedBody });
    assert.equal(result, "unverified_shape");
    assert.notEqual(result, "verified");
  });
});

import { timingSafeEqual } from "crypto";

function readBearerToken(header: string | null): string | null {
  if (!header) return null;
  return header.startsWith("Bearer ") ? header.slice(7) : header;
}

function secretsMatch(provided: string | null, secret: string): boolean {
  if (!provided || provided.length !== secret.length) return false;
  try {
    return timingSafeEqual(Buffer.from(provided), Buffer.from(secret));
  } catch {
    return false;
  }
}

/** Pay Hero POST body shape — no HMAC; see docs.payhero.co.ke payment callback.
 * Matching this shape is NOT authentication — PayHero doesn't sign callbacks, so this
 * only tells the caller "this looks like it might be real," never "this is real."
 * See PayHeroVerification below for how callers must treat each outcome. */
export function isPayHeroCallbackPayload(body: Record<string, unknown>): boolean {
  const response = (body.response ?? body) as Record<string, unknown>;
  return !!(
    response.ExternalReference ??
    response.external_reference ??
    response.CheckoutRequestID ??
    response.checkout_request_id
  );
}

/**
 * - "verified": shared-secret header/query matched. The webhook body can be trusted directly.
 * - "unverified_shape": no secret matched (PayHero doesn't reliably echo one back), but the
 *   body has the right shape. NOT proof of authenticity — a forged request with a guessable
 *   reference produces the same result. Callers MUST NOT trust this body's claimed outcome;
 *   they must independently re-check the transaction with PayHero's own status API
 *   (see reconcilePayHeroCallback in payhero-status.ts) before treating anything as paid.
 * - "rejected": doesn't even look like a real callback. Reject outright.
 */
export type PayHeroVerification = "verified" | "unverified_shape" | "rejected";

/** Verify PayHero callback using shared secret header/query; falls back to shape-only. */
export function verifyPayHeroCallback(
  req: Request,
  options?: { body?: Record<string, unknown> },
): PayHeroVerification {
  const secret = process.env.PAYHERO_CALLBACK_SECRET;
  if (!secret) {
    return process.env.NODE_ENV !== "production" ? "verified" : "rejected";
  }

  const headerToken =
    readBearerToken(req.headers.get("x-payhero-signature")) ??
    readBearerToken(req.headers.get("x-callback-secret")) ??
    readBearerToken(req.headers.get("authorization"));

  if (secretsMatch(headerToken, secret)) return "verified";

  const queryToken = new URL(req.url).searchParams.get("secret");
  if (secretsMatch(queryToken, secret)) return "verified";

  if (options?.body && isPayHeroCallbackPayload(options.body)) return "unverified_shape";

  return "rejected";
}

/** Callback URL with secret query param for providers that cannot send custom headers. */
export function payHeroCallbackUrl(): string {
  const base =
    process.env.PAYHERO_CALLBACK_URL?.trim() ||
    `${process.env.NEXT_PUBLIC_APP_URL?.trim() || process.env.APP_URL?.trim() || "https://solera.app"}/api/payhero/callback`;
  const secret = process.env.PAYHERO_CALLBACK_SECRET;
  if (!secret) return base;
  const url = new URL(base);
  url.searchParams.set("secret", secret);
  return url.toString();
}

import path from "path";
import type { NextConfig } from "next";

const securityHeaders = [
  { key: "X-Frame-Options", value: "DENY" },
  { key: "X-Content-Type-Options", value: "nosniff" },
  { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
  {
    key: "Strict-Transport-Security",
    value: "max-age=31536000; includeSubDomains",
  },
  {
    key: "Content-Security-Policy",
    value: [
      "default-src 'self'",
      "script-src 'self' 'unsafe-inline' 'unsafe-eval' https://conversations-widget.brevo.com",
      "style-src 'self' 'unsafe-inline'",
      "img-src 'self' data: blob: https://*.brevo.com https://*.sendinblue.com https://*.stream-io-cdn.com",
      "font-src 'self'",
      "connect-src 'self' https://api.turso.tech https://*.turso.io https://conversations-widget.brevo.com https://*.brevo.com https://chat.stream-io-api.com wss://chat.stream-io-api.com https://*.stream-io-api.com",
      "frame-src 'self' https://conversations-widget.brevo.com",
      "frame-ancestors 'none'",
      "base-uri 'self'",
      "form-action 'self'",
    ].join("; "),
  },
];

const nextConfig: NextConfig = {
  webpack: (config) => {
    config.resolve.alias = {
      ...config.resolve.alias,
      "@": path.resolve(process.cwd(), "src"),
    };
    return config;
  },
  poweredByHeader: false,
  async headers() {
    return [{ source: "/(.*)", headers: securityHeaders }];
  },
  // Proxy the consumer-marketplace API paths to the Django backend server-side, via
  // SOLERA0_API_URL — a server-only env var, never exposed to the browser. This means:
  //  - the browser only ever calls same-origin /api/*, so no CORS setup is needed on
  //    Django and the CSP connect-src above never needs to list an external backend host
  //  - the backend's real URL is never present in client-side JS at all
  // NOTE: deliberately does NOT touch /api/auth/* — that path is already owned by the
  // inherited NextAuth catch-all route (src/app/api/auth/[...nextauth]/route.ts), which
  // the (app)/(auth) B2B dashboard still needs. Django's own auth endpoints are proxied
  // under /api/consumer-auth/* instead (see src/lib/api.ts) to avoid colliding with it.
  async rewrites() {
    const backend = process.env.SOLERA0_API_URL;
    if (!backend) return [];
    const base = backend.replace(/\/$/, "");
    return [
      { source: "/api/pharmacies/:path*", destination: `${base}/api/pharmacies/:path*` },
      { source: "/api/marketplace/:path*", destination: `${base}/api/marketplace/:path*` },
      { source: "/api/consumer/:path*", destination: `${base}/api/consumer/:path*` },
      { source: "/api/consumer-auth/:path*", destination: `${base}/api/auth/:path*` },
    ];
  },
};

export default nextConfig;

