            <p className="mt-2 font-semibold text-green-700">Application received</p>
            <p className="mt-1 text-sm text-green-800">{done.message}</p>
            <Link href="/" className="mt-4 inline-block">
              <Button variant="outline">Back to store</Button>
            </Link>
          </div>
        ) : (
          <form onSubmit={submit} className="mt-8 space-y-4 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-6">
            <div>
              <label className="text-sm font-medium text-[var(--text-primary)]">Pharmacy name</label>
              <input required value={form.name} onChange={(e) => set("name", e.target.value)} className="mt-1 w-full rounded-lg border border-[var(--border)] px-3 py-2 text-sm outline-none" />
            </div>
            <div className="grid gap-4 sm:grid-cols-2">
              <div>
                <label className="text-sm font-medium text-[var(--text-primary)]">Contact phone</label>
                <input required value={form.contact_phone} onChange={(e) => set("contact_phone", e.target.value)} className="mt-1 w-full rounded-lg border border-[var(--border)] px-3 py-2 text-sm outline-none" />
              </div>
              <div>
                <label className="text-sm font-medium text-[var(--text-primary)]">Contact email</label>
                <input value={form.contact_email} onChange={(e) => set("contact_email", e.target.value)} className="mt-1 w-full rounded-lg border border-[var(--border)] px-3 py-2 text-sm outline-none" />
              </div>
            </div>
            <div className="grid gap-4 sm:grid-cols-2">
              <div>
                <label className="text-sm font-medium text-[var(--text-primary)]">City</label>
                <input required value={form.city} onChange={(e) => set("city", e.target.value)} className="mt-1 w-full rounded-lg border border-[var(--border)] px-3 py-2 text-sm outline-none" />
              </div>
              <div>
                <label className="text-sm font-medium text-[var(--text-primary)]">County</label>
                <input value={form.county} onChange={(e) => set("county", e.target.value)} className="mt-1 w-full rounded-lg border border-[var(--border)] px-3 py-2 text-sm outline-none" />
              </div>
            </div>
            <div>
              <label className="text-sm font-medium text-[var(--text-primary)]">Address</label>
              <input value={form.address} onChange={(e) => set("address", e.target.value)} className="mt-1 w-full rounded-lg border border-[var(--border)] px-3 py-2 text-sm outline-none" />
            </div>
            <div>
              <label className="text-sm font-medium text-[var(--text-primary)]">PPB licence number</label>
              <input value={form.ppb_license} onChange={(e) => set("ppb_license", e.target.value)} placeholder="Verified before public listing" className="mt-1 w-full rounded-lg border border-[var(--border)] px-3 py-2 text-sm outline-none" />
            </div>
            <Button type="submit" disabled={loading} className="w-full">
              {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : "Submit application"}
            </Button>
          </form>
        )}

        <p className="mt-6 text-center text-xs text-[var(--text-secondary)]">
          Already on Solera? Your stock connects automatically once approved.
        </p>
      </div>
    </MarketingShell>
  );
}

