"use client";
/**
 * Solera.0 API client. Talks to the Django backend via same-origin /api/* paths,
 * proxied server-side by next.config.ts's rewrites() (see src/lib/env.ts).
 * Consumer auth uses phone OTP; the JWT is stored in localStorage and sent as Bearer.
 */
import { getSolera0Api } from "@/lib/env";

const TOKEN_KEY = "solera0_jwt";
const PHONE_KEY = "solera0_phone";

export function getToken(): string | null {
  if (typeof window === "undefined") return null;
  return localStorage.getItem(TOKEN_KEY);
}
export function getConsumerPhone(): string | null {
  if (typeof window === "undefined") return null;
  return localStorage.getItem(PHONE_KEY);
}
export function setSession(token: string, phone: string) {
  localStorage.setItem(TOKEN_KEY, token);
  localStorage.setItem(PHONE_KEY, phone);
}
export function clearSession() {
  localStorage.removeItem(TOKEN_KEY);
  localStorage.removeItem(PHONE_KEY);
}

async function request(path: string, opts: RequestInit = {}) {
  const base = getSolera0Api();
  const headers = new Headers(opts.headers);
  headers.set("Content-Type", "application/json");
  const token = getToken();
  if (token) headers.set("Authorization", `Bearer ${token}`);
  const res = await fetch(`${base}${path}`, { ...opts, headers });
  const text = await res.text();
  let data: any = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  if (!res.ok) {
    throw new Error((data && data.error) || `Request failed (${res.status})`);
  }
  return data;
}


export const pharmacyApi = {
  apply: (payload: any) =>
    request("/api/pharmacies/apply/", { method: "POST", body: JSON.stringify(payload) }),
  listApplications: (adminEmail: string) =>
    request("/api/pharmacies/applications/", { headers: { "x-admin-email": adminEmail } }),
  approve: (appId: number, adminEmail: string, turso: { turso_db_url: string; db_token_encrypted: string }) =>
    request(`/api/pharmacies/applications/${appId}/approve/`, {
      method: "POST",
      headers: { "x-admin-email": adminEmail },
      body: JSON.stringify(turso),
    }),
};

export const solera0 = {
  // Proxied to Django's /api/auth/* under a different local prefix — /api/auth/* itself
  // is already owned by the inherited NextAuth catch-all route (see next.config.ts).
  requestOtp: (phone: string) =>
    request("/api/consumer-auth/request-otp/", { method: "POST", body: JSON.stringify({ phone }) }),
  verifyOtp: (phone: string, otp: string) =>
    request("/api/consumer-auth/verify-otp/", {
      method: "POST",
      body: JSON.stringify({ phone, otp, role: "consumer" }),
    }),
  search: (q: string, city?: string) =>
    request(`/api/marketplace/search/?q=${encodeURIComponent(q)}${city ? `&city=${encodeURIComponent(city)}` : ""}`),
  placeOrder: (payload: any) =>
    request("/api/consumer/orders/", { method: "POST", body: JSON.stringify(payload) }),
  myOrders: () => request("/api/consumer/orders/mine/"),
  orderDetail: (id: string) => request(`/api/consumer/orders/${id}/`),
};

