"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { Search, ShoppingCart, MapPin, CheckCircle2, Loader2 } from "lucide-react";
import { MarketingShell } from "@/components/marketing/marketing-shell";
import { Button } from "@/components/ui/button";
import { solera0, getToken, getConsumerPhone, setSession } from "@/lib/api";

type SearchResult = {
  pharmacy_id: string;
  pharmacy: string;
  city: string;
  distance_km?: number;
  in_stock: boolean;
  quantity?: number;
  unit_price: number;
  product_name: string;
  batch_id?: string;
};

type CartItem = SearchResult & { cartQty: number };

export default function MarketplacePage() {
  const [query, setQuery] = useState(
    typeof window !== "undefined"
      ? new URLSearchParams(window.location.search).get("q") ?? ""
      : "",
  );
  const [city, setCity] = useState("");
  const [results, setResults] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (query.trim()) doSearch();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const [error, setError] = useState("");
  const [cart, setCart] = useState<Record<string, CartItem>>({});
  const [phone, setPhone] = useState(getConsumerPhone() ?? "");
  const [otp, setOtp] = useState("");
  const [otpSent, setOtpSent] = useState(false);
  const [authed, setAuthed] = useState(Boolean(getToken()));
  const [placing, setPlacing] = useState(false);
  const [lastOrder, setLastOrder] = useState<any>(null);

  const doSearch = async () => {
    if (!query.trim()) return;
    setLoading(true);
    setError("");
    try {
      const data = await solera0.search(query.trim(), city.trim() || undefined);
      setResults(data.results ?? []);
    } catch (e: any) {
      setError(e.message || "Search failed");
    } finally {
      setLoading(false);
    }
  };

  const addToCart = (r: SearchResult) => {
    setCart((prev) => {
      const key = `${r.pharmacy_id}:${r.product_name}`;
      const existing = prev[key];
      const max = r.quantity ?? 99;
      const nextQty = Math.min((existing?.cartQty ?? 0) + 1, max);
      return { ...prev, [key]: { ...r, cartQty: nextQty } };
    });
  };

  const setQty = (key: string, qty: number) => {
    setCart((prev) => {
      const item = prev[key];
      if (!item) return prev;
      if (qty <= 0) {
        const { [key]: _omit, ...rest } = prev;
        return rest;
      }
      return { ...prev, [key]: { ...item, cartQty: Math.min(qty, item.quantity ?? 99) } };
    });
  };

  const cartItems = Object.values(cart);
  const total = cartItems.reduce((s, i) => s + i.unit_price * i.cartQty, 0);

  const sendOtp = async () => {
    setError("");
    try {
      const res = await solera0.requestOtp(phone);
      setOtpSent(true);
      if (res.dev_otp) setError(`(dev) OTP: ${res.dev_otp}`);
    } catch (e: any) {
      setError(e.message || "Could not send OTP");
    }
  };

  const verifyOtp = async () => {
    setError("");
    try {
      const res = await solera0.verifyOtp(phone, otp);
      setSession(res.access, phone);
      setAuthed(true);
    } catch (e: any) {
      setError(e.message || "Invalid OTP");
    }
  };

  const checkout = async () => {
    if (!authed) {
      setError("Please verify your phone first.");
      return;
    }
    const byPharmacy: Record<string, CartItem[]> = {};
    for (const it of cartItems) {
      (byPharmacy[it.pharmacy_id] ??= []).push(it);
    }
    setPlacing(true);
    setError("");
    try {
      const orders = [];
      for (const [pharmacyId, items] of Object.entries(byPharmacy)) {
        const payload = {
          phone,
          pharmacy_id: pharmacyId,
          fulfilment_type: "pickup",
          items: items.map((i) => ({
            product_id: i.batch_id ?? i.product_name,
            product_name: i.product_name,
            quantity: i.cartQty,
            unit_price: i.unit_price,
            batch_id: i.batch_id ?? "",
          })),
        };
        const res = await solera0.placeOrder(payload);
        orders.push(res);
      }
      setLastOrder(orders);
      setCart({});
    } catch (e: any) {
      setError(e.message || "Checkout failed");
    } finally {
      setPlacing(false);
    }
  };

  return (
    <MarketingShell>
      <div className="mx-auto max-w-5xl px-6 py-12">
        <div className="text-center">
          <h1 className="text-3xl font-bold text-[var(--text-primary)] md:text-4xl">
            Solera Marketplace
          </h1>
          <p className="mt-3 text-[var(--text-secondary)]">
            Search live pharmacy stock near you. Order online, pick up at the pharmacy.
          </p>
        </div>

        {error && (
          <p className="mt-4 rounded-lg border border-amber-300 bg-amber-50 px-4 py-2 text-sm text-amber-800">
            {error}
          </p>
        )}

        <div className="mt-8 flex flex-col gap-3 sm:flex-row">
          <div className="flex flex-1 items-center gap-2 rounded-xl border border-[var(--border)] bg-[var(--surface)] px-3">
            <Search className="h-4 w-4 text-[var(--text-secondary)]" />
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && doSearch()}
              placeholder="Search medicine, e.g. Panadol"
              className="w-full bg-transparent py-3 text-sm outline-none"
            />
          </div>
          <input
            value={city}
            onChange={(e) => setCity(e.target.value)}
            placeholder="City (optional)"
            className="rounded-xl border border-[var(--border)] bg-[var(--surface)] px-3 py-3 text-sm outline-none sm:w-48"
          />
          <Button onClick={doSearch} disabled={loading}>
            {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : "Search"}
          </Button>
        </div>

        <div className="mt-8 space-y-3">
          {results.map((r, i) => {
            const key = `${r.pharmacy_id}:${r.product_name}`;
            const inCart = cart[key]?.cartQty ?? 0;
            return (
              <div key={i} className="flex items-center justify-between rounded-xl border border-[var(--border)] bg-[var(--surface)] p-4">
                <div>
                  <p className="font-medium text-[var(--text-primary)]">{r.product_name}</p>
                  <p className="text-sm text-[var(--text-secondary)] flex items-center gap-1">
                    <MapPin className="h-3 w-3" /> {r.pharmacy}
                    {r.city ? ` . ${r.city}` : ""}
                    {r.distance_km != null ? ` . ${r.distance_km} km` : ""}
                  </p>
                  <p className="text-sm">
                    {r.in_stock ? (
                      <span className="text-green-600">In stock ({r.quantity})</span>
                    ) : (
                      <span className="text-red-500">Out of stock</span>
                    )}{" "}
                    . KES {r.unit_price}
                  </p>
                </div>
                <div className="flex items-center gap-2">
                  {inCart > 0 && (
                    <>
                      <Button variant="outline" size="sm" onClick={() => setQty(key, inCart - 1)}>-</Button>
                      <span className="w-6 text-center">{inCart}</span>
                      <Button variant="outline" size="sm" onClick={() => setQty(key, inCart + 1)}>+</Button>
                    </>
                  )}
                  <Button size="sm" disabled={!r.in_stock} onClick={() => addToCart(r)}>
                    <ShoppingCart className="h-4 w-4" /> Add
                  </Button>
                </div>
              </div>
            );
          })}
          {results.length === 0 && !loading && (
            <p className="text-center text-sm text-[var(--text-secondary)]">
              Search to see live pharmacy stock from Solera-powered pharmacies.
            </p>
          )}
        </div>

        {cartItems.length > 0 && (
          <div className="mt-10 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-6">
            <h2 className="text-lg font-semibold text-[var(--text-primary)]">Your order</h2>
            <ul className="mt-3 space-y-2 text-sm">
              {cartItems.map((i) => (
                <li key={`${i.pharmacy_id}:${i.product_name}`} className="flex justify-between">
                  <span>{i.cartQty} x {i.product_name} ({i.pharmacy})</span>
                  <span>KES {i.unit_price * i.cartQty}</span>
                </li>
              ))}
            </ul>
            <p className="mt-3 border-t border-[var(--border)] pt-3 font-semibold">Total: KES {total}</p>

            {!authed ? (
              <div className="mt-4 space-y-2">
                {!otpSent ? (
                  <div className="flex gap-2">
                    <input
                      value={phone}
                      onChange={(e) => setPhone(e.target.value)}
                      placeholder="Phone number"
                      className="flex-1 rounded-lg border border-[var(--border)] px-3 py-2 text-sm outline-none"
                    />
                    <Button onClick={sendOtp}>Send OTP</Button>
                  </div>
                ) : (
                  <div className="flex gap-2">
                    <input
                      value={otp}
                      onChange={(e) => setOtp(e.target.value)}
                      placeholder="Enter OTP"
                      className="flex-1 rounded-lg border border-[var(--border)] px-3 py-2 text-sm outline-none"
                    />
                    <Button onClick={verifyOtp}>Verify</Button>
                  </div>
                )}
              </div>
            ) : (
              <Button className="mt-4 w-full" onClick={checkout} disabled={placing}>
                {placing ? <Loader2 className="h-4 w-4 animate-spin" /> : "Place order (Pay with M-Pesa)"}
              </Button>
            )}
          </div>
        )}

        {lastOrder && (
          <div className="mt-6 rounded-2xl border border-green-200 bg-green-50 p-6">
            <div className="flex items-center gap-2 text-green-700">
              <CheckCircle2 className="h-5 w-5" />
              <span className="font-semibold">Orders placed!</span>
            </div>
            <p className="mt-2 text-sm text-green-800">
              M-Pesa STK push initiated. Complete payment on your phone. Your pickup OTP appears here
              once payment clears.
            </p>
            <pre className="mt-3 overflow-auto rounded bg-white p-3 text-xs">
              {JSON.stringify(lastOrder, null, 2)}
            </pre>
            <Button variant="outline" className="mt-3" onClick={() => setLastOrder(null)}>
              Done
            </Button>
          </div>
        )}
      </div>
    </MarketingShell>
  );
}

